with metrics as (select *, corr(age, credit_limit) over (partition by city) as corr_age_credit_limit, first_value(city) ignore nulls over w_hist as first_known_city, dense_rank() over (partition by country order by age nulls first) as age_dense_rank from customers window w_hist as (partition by date_trunc('week', signup_date), segment order by credit_limit, id rows between unbounded preceding and current row)) select id, name, email, country, city, signup_date, is_active, age, corr_age_credit_limit, case when country rlike '^(JP|SG)$' then 'PRIORITY' when country rlike '^(TH|US)$' then 'CORE' else 'OTHER_ZONE' end as country_zone from metrics order by id nulls first, age desc limit 10;
